from decimal import Decimal

import pytest

from payment.domain.authorization_outcome import AuthorizationOutcome
from payment.domain.money import Money


def test_currency_is_upper_cased() -> None:
    assert Money(Decimal("1"), "eur").currency == "EUR"


def test_smallest_positive_amount_is_accepted() -> None:
    assert Money(Decimal("0.01"), "EUR").amount == Decimal("0.01")


@pytest.mark.parametrize("amount", [Decimal("0"), Decimal("-1")])
def test_non_positive_amount_is_rejected(amount: Decimal) -> None:
    with pytest.raises(ValueError, match="An amount must be positive."):
        Money(amount, "EUR")


@pytest.mark.parametrize("currency", ["", "   "])
def test_blank_currency_is_rejected(currency: str) -> None:
    with pytest.raises(ValueError, match="A currency is required."):
        Money(Decimal("1"), currency)


def test_outcome_values() -> None:
    assert AuthorizationOutcome.DECLINED.value == "declined"
    assert AuthorizationOutcome.APPROVED.value == "approved"
E
cat >> tests/unit/test_authorize_payment.py <<'E'


def test_receipt_body_describes_amount_and_outcome() -> None:
    receipts = InMemoryReceiptStore()
    handler = AuthorizePayment(AlwaysAnswers(AuthorizationOutcome.DECLINED), receipts)

    handler.handle("ORD-3", Money(Decimal("42.50"), "eur"))

    assert receipts.saved == {"ORD-3": "EUR 42.50 -> DECLINED"}


def test_gateway_receives_reference_and_amount() -> None:
    seen = []

    class Spy:
        def authorize(self, reference, amount):
            seen.append((reference, amount))
            return AuthorizationOutcome.APPROVED

    money = Money(Decimal("5"), "EUR")
    AuthorizePayment(Spy(), InMemoryReceiptStore()).handle("ORD-4", money)

    assert seen == [("ORD-4", money)]
